import React, { useState } from 'react';
import './Dashboard.css';

export default function Dashboard({ products, setProducts }) {

  const [name, setName] = useState('');
  const [price, setPrice] = useState('');
  const [color, setColor] = useState('');
  const [type, setType] = useState('');
  const [description, setDescription] = useState('');

  const add = () => {
    if (!name.trim() || !price || !color.trim() || !type.trim() || !description.trim()) {
      alert('Будь ласка, заповніть усі обов\'язкові поля.');
      return;
    }

    const priceValue = Number(price);
    if (priceValue < 1 || isNaN(priceValue)) {
      alert('Ціна має бути не менше 1 і бути коректним числом.');
      return;
    }

    setProducts([...products, {
      id: Date.now(),
      name: name.trim(),
      price: priceValue,
      color: color.trim(),
      type: type.trim(),
      description: description.trim()
    }]);

    setName('');
    setPrice('');
    setColor('');
    setType('');
    setDescription('');
  };

  const remove = (id) => {
    setProducts(products.filter(p => p.id !== id));
  };

  return (
    <div className="dashboard-container">

      <h2 className="dash-title">Dashboard — Manage Products</h2>

      <div className="add-panel">
        <input
          className="dash-input"
          placeholder="Product name"
          value={name}
          onChange={e => setName(e.target.value)}
        />
        <input
          className="dash-input"
          type="number"
          placeholder="Price"
          value={price}
          onChange={e => setPrice(e.target.value)}
        />
        <input
          className="dash-input"
          placeholder="Color (e.g., Grey, Black)"
          value={color}
          onChange={e => setColor(e.target.value)}
        />
        <select
          className="dash-input"
          value={type}
          onChange={e => setType(e.target.value)}
        >
            <option value="">-- Select Type --</option>
            <option value="phone">Phone</option>
            <option value="audio">Audio</option>
            <option value="tablet">Tablet</option>
            <option value="accessory">Accessory</option>
        </select>
        
        <textarea
            className="dash-input full-width"
            placeholder="Product description"
            rows="3"
            value={description}
            onChange={e => setDescription(e.target.value)}
        />

        <button className="btn-add full-width" onClick={add}>
            Add product
        </button>
      </div>

      <h3 className="list-title">Current Products List</h3>
      <ul className="product-list">
        {products.map(p => (
          <li key={p.id} className="product-item">
            <span className="product-info">
                <strong>{p.name}</strong> ({p.type}) — {p.price}$ <br/> 
                <small>Колір: {p.color}</small>
            </span>
            <button className="btn-delete" onClick={() => remove(p.id)}>
                Delete
            </button>
          </li>
        ))}
      </ul>

    </div>
  );
}
